import{_ as t,c as o,o as r,ag as s}from"./chunks/framework.Cycwnjj0.js";const h=JSON.parse('{"title":"How to Get Support","description":"","frontmatter":{},"headers":[],"relativePath":"guide/support/how-to-get-support.md","filePath":"guide/support/how-to-get-support.md"}'),i={name:"guide/support/how-to-get-support.md"};function n(a,e,u,l,p,c){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="how-to-get-support" tabindex="-1">How to Get Support <a class="header-anchor" href="#how-to-get-support" aria-label="Permalink to &quot;How to Get Support&quot;">​</a></h1><p>If you&#39;ve reviewed the Docs guides and are still encountering a problem with AzonPress, our dedicated support team is here to help.</p><h2 id="how-to-contact-support" tabindex="-1">How to Contact Support <a class="header-anchor" href="#how-to-contact-support" aria-label="Permalink to &quot;How to Contact Support&quot;">​</a></h2><p>To ensure you receive the quickest and most effective assistance, please follow these guidelines when contacting us:</p><ol><li><p><strong>Visit the WPManageNinja Support Portal:</strong> Go to the WPManageNinja website. This is the primary channel for submitting support tickets.</p></li><li><p><strong>Submit a Support Ticket:</strong></p><ul><li>Log in to your <a href="https://wpmanageninja.com/account/" target="_blank" rel="noreferrer">account</a> (this will be your account on our main <a href="https://wpmanageninja.com/" target="_blank" rel="noreferrer">WPManageNinja.com</a> site).</li><li>Navigate to the &quot;Support Tickets&quot; section.</li><li>Click on &quot;Create Ticket.&quot;</li></ul></li><li><p><strong>Provide Detailed Information:</strong> When submitting your ticket, please include as much detail as possible. This helps our team understand your issue quickly and provide a precise solution. Include:</p><ul><li><strong>A Clear Description of the Problem:</strong> Explain what you are trying to achieve and what is happening instead. (e.g., &quot;I am trying to connect my Amazon API keys, but I get an &#39;Invalid Signature&#39; error,&quot; or &quot;My product table is showing &#39;Product not found&#39; for all ASINs.&quot;)</li><li><strong>Steps to Reproduce:</strong> List the exact steps you take that lead to the issue.</li><li><strong>Screenshots or Screen Recordings:</strong> Visual aids are incredibly helpful for diagnosing problems. Please include screenshots of your AzonPress settings (especially API and region settings) and the error you see on the front end.</li><li><strong>Error Messages:</strong> If you see any error messages on your screen or in your WordPress debug log, copy and paste them.</li><li><strong>Your WordPress Version.</strong></li><li><strong>Your AzonPress Plugin Version.</strong></li><li><strong>Any Other Plugins Active on Your Site:</strong> List them, especially if they are related to caching (e.g., WP Rocket, LiteSpeed), security (e.g., Wordfence), or page builders (e.g., Elementor, Divi), as these are the most common sources of conflict.</li></ul></li><li><p><strong>Support Hours:</strong> Our support team operates during business hours. We strive to respond to all inquiries as quickly as possible.</p></li></ol><p>We are committed to helping you succeed with AzonPress!</p>',6)])])}const d=t(i,[["render",n]]);export{h as __pageData,d as default};
